(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[8755],{9621:(e,l,a)=>{"use strict";a.r(l),a.d(l,{data:()=>t});const t={key:"v-88785fbc",path:"/pages/self-daily/daily-log/2025-08-02/",title:"",lang:"zh-CN",frontmatter:{sidebar:!1},excerpt:"",headers:[{level:3,title:"梦回高中教室",slug:"梦回高中教室",children:[]}],filePathRelative:"pages/self-daily/daily-log/2025-08-02/README.md",git:{updatedTime:175438096e4,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:1}]}}},8361:(e,l,a)=>{"use strict";a.r(l),a.d(l,{default:()=>i});var t=a(6252);const s=(0,t.Wm)("h3",{id:"梦回高中教室"},[(0,t.Wm)("a",{class:"header-anchor",href:"#梦回高中教室"},"#"),(0,t.Uk)(" 梦回高中教室")],-1),r=(0,t.Wm)("p",null,"   好久没有写日志了，正好今天有时间然后昨天做了一个重回高中教室的梦所以，在此留笔回忆那些时光。 之前做梦梦到最多的是我放弃了去江南大学学习的计划决定再次去复读，因为语文没有考及格的原因觉得自己还有很大的提升空间，但整个复习过程中自己并没有复习化学，感觉化学题都不会做，心里非常地急马上又要高考了。感觉自己一年多都没咋做化学题，甚至非常后悔再次复读。但这次不同，这次梦见自己不会做的题是数学，我之前都觉得数学没啥难的，往往也是我比较自信的学科。但由于上课出小差，被数学老师叫到了讲台上去做习题。望着那个题目感觉像是在看天书，我感觉这个梦就是回到了过去的高中教室，但是脑子没带回去。害得我非常着急，最后拿着粉笔半天没写一个字。最后老师叫了一个平时学习不咋好的同学完成了回答，给我急得不行，咋的数学也不行了还咋继续高考啊。梦醒之后，最先回到的过往片段还是数学老师在上面解题，用了一种比较新颖的解题思路，然后又讲了下一题，我就自告奋勇的举手去讲台用新的解题思路完成了作答，还得到了老师夸赞，说实话那是我为数不多的自己主动上讲台作答。本来是一个美好的回忆，硬是梦成了一个噩梦。还有旁边有个调皮的同学一直在旁边影响我学习，我就掀桌子把他揍了一顿。那时候的我怎么可能这么冲动呢。梦真是记忆碎片的随意拼凑。",-1),i={render:function(e,l){return(0,t.wg)(),(0,t.j4)(t.HY,null,[s,r],64)}}}}]);